import { Capacitor } from '@capacitor/core';
import { CapacitorSQLiteKyselyConnection } from './CapacitorSQLiteKyselyConnection';
export class CapacitorSQLiteKyselyDriver {
    #config;
    #sqlite;
    #platform = '';
    constructor(client, config) {
        this.#sqlite = client;
        this.#config = config;
        this.#platform = Capacitor.getPlatform();
    }
    async init() {
        if (this.#platform !== 'web') {
            return;
        }
        await this.#sqlite.initWebStore();
    }
    async acquireConnection() {
        const ret = await this.#sqlite.checkConnectionsConsistency();
        const isConn = (await this.#sqlite.isConnection(this.#config.name, this.#config.readonly)).result;
        if (ret.result && isConn) {
            const db = await this.#sqlite.retrieveConnection(this.#config.name, this.#config.readonly);
            return new CapacitorSQLiteKyselyConnection(this.#config, db, this.#sqlite);
        }
        const db = await this.#sqlite.createConnection(this.#config.name, this.#config.encryption, this.#config.mode, this.#config.version, this.#config.readonly);
        await db.open();
        return new CapacitorSQLiteKyselyConnection(this.#config, db, this.#sqlite);
    }
    async beginTransaction(connection, settings) {
        await connection.db.beginTransaction();
    }
    async commitTransaction(connection) {
        await connection.db.commitTransaction();
        if (this.#platform !== 'web') {
            return;
        }
        this.#sqlite.saveToStore(this.#config.name);
    }
    async rollbackTransaction(connection) {
        await connection.db.rollbackTransaction();
    }
    async releaseConnection(connection) {
        // not implemented
    }
    async destroy() {
        this.#sqlite.closeConnection(this.#config.name, this.#config.readonly);
    }
}
